cept_ids": ["paths", "states"], "index": 0, "total": 2}, "position": {"concept_id": "paths", "goal": "Predict interference", "next_step": "Start the lesson", "progress": ""}, "prerequisites": [], "next_concept_id": "states", "sources": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2", "id": "line-2", "locator": {"line": 2}, "text": "Two paths reach the same detector, each with a complex amplitude.", "stale": false}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3", "id": "line-3", "locator": {"line": 3}, "text": "The total amplitude is the sum of the path amplitudes.", "stale": false}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "id": "line-4", "locator": {"line": 4}, "text": "The probability is the squared magnitude of the total amplitude.", "stale": false}]}, "active_branch": null, "due_explanations": [], "unanswered_questions": [], "recent_interactions": [{"id": "stream-user:4ef635f9-7a86-4af8-b9c0-0db1481a8610", "role": "user", "text": "Teach this section fully around the current goal: start with the intuition behind its core question, then give the precise definitions, statements or methods with their conditions and the necessary derivations, and include a worked example.", "concept_id": "paths", "source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_conc