INSERT INTO "documents" VALUES('interactions','stream:practice-84c72011-3607-4b46-b67d-41846eab93f7','{"id": "stream:practice-84c72011-3607-4b46-b67d-41846eab93f7", "role": "assistant", "text": "{\"questions\": [{\"question\": \"Two paths have amplitudes $1/2$ and $e^{i\\\\phi}/2$. Find $P(\\\\phi)$ and when it is zero.\", \"origin\": \"self_created\", \"source_refs\": []}]}", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 3}');
INSERT INTO "documents" VALUES('practice_tasks','practice-84c72011-3607-4b46-b67d-41846eab93f7:0','{"id": "practice-84c72011-3607-4b46-b67d-41846eab93f7:0", "concept_id": "paths", "question": "Two paths have amplitudes $1/2$ and $e^{i\\phi}/2$. Find $P(\\phi)$ and when it is zero.", "origin": "self_created", "source_refs": [], "status": "attempted", "history": [{"action": "hint", "feedback": "Expand $|z|^2 = z^* z$ first."}, {"action": "assess", "feedback": "$P(\\phi)$ is right; check when the cosine is $-1$.", "outcome": "needs_work", "evidence_id": "practice-evidence:practice-8fba05c6-3779-4e4e-80ec-fdee19ef2ddf", "kind": "needs_work", "answer": "P = (1 + cos phi)/2, zero at phi = 0."}, {"action": "assess", "feedback": "Right: $P = (1 + \\cos\\phi)/2$, zero at $\\phi = \\pi$.", "outcome": "passed", "evidence_id": "practice-evidence:practice-61b1976f-035b-45bc-948b-07cabdb39e3c", "kind": "hinted", "answer": "P = (1 + cos phi)/2, zero at phi = pi."}]}');
