c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2", "id": "line-2", "locator": {"line": 2}, "text": "Two paths reach the same detector, each with a complex amplitude.", "stale": false}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3", "id": "line-3", "locator": {"line": 3}, "text": "The total amplitude is the sum of the path amplitudes.", "stale": false}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "id": "line-4", "locator": {"line": 4}, "text": "The probability is the squared magnitude of the total amplitude.", "stale": false}]}, "route": [{"id": "paths", "title": "Adding path amplitudes"}, {"id": "states", "title": "States and global phase", "prerequisites": ["paths"]}, {"id": "outcomes", "title": "Measurement outcomes", "prerequisites": ["states"]}], "session": {"position": {"concept_id": "states", "goal": "Understand States and global phase", "next_step": "Begin teaching this section", "progress": ""}, "context": {"concept": {"id": "states", "title": "States and global phase", "prerequisites": ["paths"], "links": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6"}]}, "chapter": {"id": "superposition", "title": "Superposition", "concept_ids": ["paths", "states"], "index": 0, "total": 2}, "position": {"concept_id": "states", "goal": "Understand States and global phase", "next_step": "Begin teaching this section", "progress": ""}, "prerequisites": [{"id": "paths", "title": "Adding path amplitudes", "objective": "Predict interference from two amplitudes", "links": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "exercises": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "question": "Find the probability for equal amplitudes."}]}], "next_concept_id": "outcomes", "sources": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6", "id": "line-6", "locator": {"line": 6}, "text": "A state is a normalized vector; a global phase changes no probability.", "stale": false}]}, "active_branch": null, "due_explanations": [], "unanswered_questions": [], "recent_interactions": [{"id": "stream-user:0579a671-0791-4f8b-9af7-ac5bd8659dc4", "role": "user", "text": "Teach this section fully around the current goal: start with the intuition behind its core question, then give the precise definitions, statements or methods with their conditions and the necessary derivations, and include a worked example.", "concept_id": "states", "source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6"}], "source_context_concept_id": "states", "sequence": 16}, {"id": "stream:0579a671-0791-4f8b-9af7-ac5bd8659dc4", "role": "assistant", "text": "## States and global phase\n\nA state is a normalized vector.", "concept_id": "states", "supplied_source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6"}], "source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6"}], "source_context_concept_id": "states", "sequence": 17}, {"id": "stream:practice-88cf4837-b174-4f85-af5b-325e76b1de10", "role": "assistant", "text": "{\"questions\": [{\"question\": \"Two paths have amplitudes $1/2$ and $e^{i\\\\phi}/2$. Find $P(\\\\phi)$ and when it is zero.\", \"origin\": \"self_created\", \"source_refs\": []}]}", "concept_id": "states", "supplied_source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6"}], "source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6"}], "source_context_concept_id": "states", "sequence": 18}, {"id": "stream-user:recap:f104e1e8-f7c6-469a-8f61-281065d065f8", "role": "user", "text": "Recap the chapter: Superposition", "concept_id": "states", "source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6"}], "source_context_concept_id": "states", "sequence": 19}, {"id": "stream:recap:f104e1e8-f7c6-469a-8f61-281065d065f8", "role": "assistant", "text": "## Recap\n\nAmplitudes add; probabilities are squared magnitudes; a global phase changes nothing.", "concept_id": "states", "supplied_source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6"}], "source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6"}], "source_context_concept_id": "states", "sequence": 20}, {"id": "stream:practice-2ea2807c-065e-4cff-98d2-5e552fb09268", "role": "assistant", "text": "{\"questions\": [{\"question\": \"Connect interference and normalization.\", \"tests_concept_ids\": [\"paths\", \"states\"]}, {\"question\": \"Why does a global phase leave the interference pattern unchanged?\", \"tests_concept_ids\": [\"states\"]}]}", "concept_id": "states", "supplied_source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6"}], "source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-6"}], "source_context_concept_id": "states", "sequence": 21}, {"id": "stream:practice-9b244968-7b83-4e80-8723-1811697714ac", "role": "assistant", "text": "{\"questions\": [{\"question\": \"Three paths with equal amplitudes: when is the detector dark?\"}]}", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 22}, {"id": "practice-answer:practice-41d4b474-ad7c-4887-ad16-7719a3de5f72", "role": "user", "text": "When the phases are 2 pi / 3 apart.", "concept_id": "paths", "source_refs": [{"source_id": "src-d54449110f1f8adcd8c2c8d4", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e